/**
 * Build a single paste-once Apps Script file from src/*.js.
 * Apps Script loads all files in a project into one global scope, so concatenating them
 * into one file is equivalent — and far easier to install (one paste instead of 11).
 * Run:  node tools/build-bundle.mjs   → writes dist/hike-sync.gs
 * Re-run after any src change to regenerate.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const srcDir = path.join(root, 'src');

// Logical order (order is irrelevant at runtime — all share one global scope).
const ORDER = [
  'value-utils.js', 'merge-engine.js', 'hike-field-map.js', 'settings.js', 'sheet-io.js',
  'sync-log.js', 'sync-runner.js', 'csv-import.js', 'hike-api.js', 'labels-print.js', 'insights.js',
  'purge-missing.js', 'dashboard.js', 'preflight.js', 'self-test.js', 'menu.js'
];

const header = `/**
 * Hike POS → Google Sheets product sync — SINGLE-FILE BUNDLE (generated by tools/build-bundle.mjs).
 * Paste this whole file into the sheet's Apps Script editor as ONE script file.
 * THEN set the manifest: Project Settings → "Show appsscript.json" → paste src/appsscript.json
 * (it declares the OAuth2 library + Drive advanced service that Lane A and .xlsx import need).
 * Do not edit here — edit src/ and re-run the build.
 */
`;

let out = header;
for (const f of ORDER) {
  const code = fs.readFileSync(path.join(srcDir, f), 'utf8')
    .split(/\r?\n/)
    .filter((l) => !l.includes('module.exports')) // Node-test shim; harmless but noise in Apps Script
    .join('\n')
    .trim();
  out += `\n\n// ======================================================================\n// ${f}\n// ======================================================================\n${code}\n`;
}

const outPath = path.join(root, 'hike-sync.gs');
fs.writeFileSync(outPath, out, 'utf8');
console.log('Wrote ' + outPath + '  (' + ORDER.length + ' files, ' + out.split('\n').length + ' lines)');
